// Characterization tests: pin CURRENT behaviour of the orders HTTP API. Contract: test/orders-api.openapi.yaml
import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { http, HttpResponse } from 'msw'
import { setupServer } from 'msw/node'
import { createApp } from '../src/app.mjs'
import { createPricingClient } from '../src/pricing-client.mjs'

const pricingApi = 'http://pricing.test'
const prices = { A: 10, B: 60, C: 0.5, D: 101 }
const pricingServer = setupServer(
  http.get(`${pricingApi}/prices/:sku`, ({ params }) => HttpResponse.json(params.sku in prices ? { price: prices[params.sku] } : {})),
)
let server, base

before(async () => {
  pricingServer.listen({ onUnhandledRequest: 'error' })
  server = createServer(createApp({ pricing: createPricingClient(pricingApi) }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(async () => {
  pricingServer.close()
  await new Promise((r) => server.close(r))
})

const post = (body, raw = false) => fetch(`${base}/orders`, { method: 'POST', body: raw ? body : JSON.stringify(body) })
const create = async (items) => {
  const res = await post({ items })
  return { res, body: await res.json() }
}

test('POST /orders creates an order: 201, json, string id, items echoed, total', async () => {
  const { res, body } = await create([{ sku: 'A', qty: 2 }])
  assert.equal(res.status, 201)
  assert.equal(res.headers.get('content-type'), 'application/json')
  assert.equal(typeof body.id, 'string')
  assert.deepEqual(body.items, [{ sku: 'A', qty: 2 }])
  assert.equal(body.total, 20)
  assert.deepEqual(Object.keys(body).sort(), ['id', 'items', 'total'])
})

test('POST /orders ids are sequential strings', async () => {
  const a = (await create([{ sku: 'A', qty: 1 }])).body.id
  const b = (await create([{ sku: 'A', qty: 1 }])).body.id
  assert.equal(Number(b), Number(a) + 1)
})

test('POST /orders sums several lines', async () => {
  const { body } = await create([{ sku: 'A', qty: 1 }, { sku: 'B', qty: 1 }])
  assert.equal(body.total, 70)
})

test('POST /orders: no discount at exactly 100 (strictly greater than)', async () => {
  assert.equal((await create([{ sku: 'A', qty: 10 }])).body.total, 100)
})

test('POST /orders: 10% discount above 100, then floored', async () => {
  assert.equal((await create([{ sku: 'A', qty: 11 }])).body.total, 99) // 110 -> 99
  assert.equal((await create([{ sku: 'D', qty: 1 }])).body.total, 90) // 90.9 -> 90
})

test('POST /orders: total is floored, not rounded', async () => {
  assert.equal((await create([{ sku: 'C', qty: 3 }])).body.total, 1) // 1.5
})

test('POST /orders: stored total is stable and returned by GET', async () => {
  const { body } = await create([{ sku: 'D', qty: 1 }])
  const got = await fetch(`${base}/orders/${body.id}`)
  assert.equal(got.status, 200)
  assert.equal(got.headers.get('content-type'), 'application/json')
  assert.deepEqual(await got.json(), body)
})

test('POST /orders without items / empty / non-array / invalid JSON / empty body -> 400', async () => {
  for (const payload of [{}, { items: [] }, { items: 'x' }, { items: {} }]) {
    const res = await post(payload)
    assert.equal(res.status, 400)
    assert.equal(res.headers.get('content-type'), 'application/json')
    assert.deepEqual(await res.json(), { error: 'items required' })
  }
  for (const raw of ['{not json', '', 'null']) {
    const res = await post(raw, true)
    assert.equal(res.status, 400, `raw=${JSON.stringify(raw)}`)
  }
})

test('POST /orders: unknown sku (pricing gives no price) -> 201 with total null', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — price undefined gives NaN, serialised as null; no validation
  const { res, body } = await create([{ sku: 'NOPE', qty: 1 }])
  assert.equal(res.status, 201)
  assert.equal(body.total, null)
})

test('POST /orders: missing qty -> 201 with total null', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — qty is not validated, price*undefined is NaN
  const { res, body } = await create([{ sku: 'A' }])
  assert.equal(res.status, 201)
  assert.equal(body.total, null)
})

test('POST /orders: negative qty is accepted', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — no qty validation
  const { res, body } = await create([{ sku: 'A', qty: -1 }])
  assert.equal(res.status, 201)
  assert.equal(body.total, -10)
})

test('GET /orders/:id unknown id -> 200 with error body', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — "not found" is returned with status 200, not 404
  const res = await fetch(`${base}/orders/does-not-exist`)
  assert.equal(res.status, 200)
  assert.equal(res.headers.get('content-type'), 'application/json')
  assert.deepEqual(await res.json(), { error: 'not found' })
})

test('unknown route -> 404 no route', async () => {
  for (const [method, path] of [['GET', '/'], ['GET', '/nope'], ['GET', '/orders'], ['GET', '/orders/1/extra'], ['PUT', '/orders'], ['DELETE', '/orders/1'], ['POST', '/orders/1']]) {
    const res = await fetch(`${base}${path}`, { method })
    assert.equal(res.status, 404, `${method} ${path}`)
    assert.deepEqual(await res.json(), { error: 'no route' })
  }
})

test('query string is ignored for routing', async () => {
  const { body } = await create([{ sku: 'A', qty: 1 }])
  const res = await fetch(`${base}/orders/${body.id}?x=1`)
  assert.deepEqual(await res.json(), body)
})
